SELECT ?iso ?poste ?p ?pLabel ?debut ?fin WHERE {
  ?o wdt:P31 wd:Q3624078; wdt:P297 ?iso.
  VALUES (?prop ?ps ?poste) { (p:P35 ps:P35 "etat") }
  ?o ?prop ?st. ?st ?ps ?p. ?st pq:P580 ?debut. FILTER(YEAR(?debut) >= 1990 && YEAR(?debut) < 2000)
  OPTIONAL { ?st pq:P582 ?fin }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,fr". } }

